def bspline_basis (x: f64) (knots: []f64) (i: i32) (k: i32): f64 =
  if k == 0
  then if knots[i] <= x && x < knots[i+1] then 1.0 else 0.0
  else
    let denom1 = knots[i+k] - knots[i]
    let denom2 = knots[i+k+1] - knots[i+1]
    let left  = if denom1 > 0.0 then (x - knots[i]) / denom1 * bspline_basis x knots i (k-1) else 0.0
    let right = if denom2 > 0.0 then (knots[i+k+1] - x) / denom2 * bspline_basis x knots (i+1) (k-1) else 0.0
    in left + right

entry kan_spline_eval [n][grid] (x: [n]f64) (coeffs: [n][grid]f64) (knots: [grid+4]f64) : [n]f64 =
  map (\i ->
    let xi = x[i]
    let basis = map (\j -> bspline_basis xi knots j 3) (iota grid)
    in f64.sum (map2 (*) basis coeffs[i])
  ) (iota n)

entry tgn_update [n] (graph: [n][n]f64) (t: f64) (emb: [n]f64) : [n][n]f64 =
  let decay = f64.exp(-t)
  in map (\i -> map (\j -> graph[i,j] * decay + emb[i] * emb[j] * 0.01) (iota n)) (iota n)

entry ssm_mamba [n] (A: [n]f64) (B: [n]f64) (C: [n]f64) (Delta: [n]f64) (x: [n]f64) : [n]f64 =
  map (\i -> A[i] * x[i] + B[i] * Delta[i] * C[i]) (iota n)

entry quantum_noise [n][shots] (states: [n]f64) (seeds: [shots]i64) : [n]f64 =
  let rng = random.rng_from_seed [seeds[0]]
  let (rngs, _) = random.split_rng shots rng
  let noises = map (\r -> let (r, v) = random.rnorm 0.0 0.01 r in v) rngs
  let total_noise = f64.sum noises / f64.i64 shots * 0.05
  in map (+ total_noise) states

entry batch_matmul [b][s][d][l] (a: [b][s][d]f64) (b_mat: [l][d]f64) : [b][s][l]f64 =
  map (\bb -> map (\ss -> map (\ll -> f64.sum (map2 (*) a[bb,ss,:] b_mat[ll,:])) (iota l)) (iota s)) (iota b)

entry reduce_loss [b][s][d] (outputs: [b][s][d]f64) (targets: [b][s]i64) : f64 =
  let preds = map (\bb -> map (\ss -> f64.sum outputs[bb,ss,:] / f64.i64 d) (iota s)) (iota b)
  let targs = map (\bb -> map (\ss -> f64.i64 targets[bb,ss] / 1000.0) (iota s)) (iota b)
  let diffs = map2 (\p t -> map2 (\pp tt -> (pp-tt)**2) p t) preds targs
  in f64.sum (flatten diffs) / f64.i64 (b*s)

entry sparse_scan [n] (qs: [n]f64) (ks: [n]f64) : [n]f64 =
  scan (+) 0.0 (map2 (+) qs ks)

entry celestial_fft [n] (signal: [n]f64) : [n]f64 =
  map (\k -> f64.sum (map (\j -> signal[j] * f64.cos(2.0*f64.pi*f64.i64 k*f64.i64 j/f64.i64 n)) (iota n))) (iota n)

def apply_kan_layer [b][s][d][grid] (inp: [b][s][d]f64) (p: [d][grid]f64) (k: [grid+4]f64) : [b][s][d]f64 =
  map (\bb -> map (\ss -> kan_spline_eval inp[bb,ss] p k) (iota s)) (iota b)

entry fmrn_forward [b][s][d][layers][grid]
  (inputs: [b][s][d]f64) (params: [layers][d][grid]f64) (knots: [grid+4]f64) : [b][s][d]f64 =
  let after_kan = reduce (\acc l -> apply_kan_layer acc params[l] knots) inputs (iota layers)
  let graph = map (\_ -> replicate d 1.0) (iota d)
  let tgn = map (\bb -> map (\ss -> map (\i -> f64.sum (tgn_update graph (f64.i32 ss) after_kan[bb,ss])[i]) (iota d)) (iota s)) (iota b)
  let A = replicate d (-0.5)
  let B = replicate d 1.0
  let C = replicate d 1.0
  let Delta = replicate d 0.1
  in map (\bb -> map (\ss -> ssm_mamba A B C Delta tgn[bb,ss]) (iota s)) (iota b)

entry fmrn_backward [b][s][d] (outputs: [b][s][d]f64) (targets: [b][s]i64) : [b][s][d]f64 =
  map (\bb -> map (\ss -> map (\dd -> 2.0 * (outputs[bb,ss,dd] - f64.i64 targets[bb,ss] / 1000.0)) (iota d)) (iota s)) (iota b)

entry celestial_zo_step [d] (params: [d]f64) (eps: f64) (grads: [d]f64) : [d]f64 =
  map2 (\p g -> p - g * eps) params grads

entry train_step [b][s][d][layers][grid]
  (inputs: [b][s][d]f64) (targets: [b][s]i64) (params: [layers][d][grid]f64) (knots: [grid+4]f64)
  : ([b][s][d]f64, f64, [layers][d][grid]f64) =
  let outs = fmrn_forward inputs params knots
  let loss = reduce_loss outs targets
  let grads = fmrn_backward outs targets
  let avg_grad = map (\dd -> f64.sum (flatten (map (\bb -> map (\ss -> grads[bb,ss,dd]) (iota s)) (iota b))) / f64.i64 (b * s)) (iota d)
  let updated = map (\l -> if l == layers - 1 then map (\dd -> map (\g -> params[l,dd,g] - avg_grad[dd] * 1e-4) (iota grid)) (iota d) else params[l]) (iota layers)
  in (outs, loss, updated)

entry benchmark [n] ( [n]f64) : f64 =
  f64.sum (map2 (*) data (map f64.i64 (iota n)))
