noncomputable structure DiffusiveNeuron where
  potential : ℝ
  conductance : ℝ
  diffusion_state : ℝ
  quantum_noise_cache : ℝ
  nested_levels : Fin 3 → ℝ

noncomputable structure JaideConfig where
  num_neurons : ℕ
  num_layers : ℕ
  learning_rate : ℝ
  lorenz_sigma : ℝ
  diffusion_coeff : ℝ
  memristor_base_r : ℝ
  quantum_shots : ℕ
  astro_knots : Fin 8 → ℝ

def defaultConfig : JaideConfig := {
  num_neurons := 18432,
  num_layers := 12,
  learning_rate := 0.001,
  lorenz_sigma := 10.0,
  diffusion_coeff := 0.05,
  memristor_base_r := 1000.0,
  quantum_shots := 156,
  astro_knots := λ _ => 0.0
}

noncomputable def updateDiffusiveNeuron (self : DiffusiveNeuron) (input : ℝ) (dt : ℝ) (config : JaideConfig) : DiffusiveNeuron :=
  let lorenz_mod := config.lorenz_sigma * (self.diffusion_state - self.potential) * dt
  let new_potential := self.potential + (input - self.potential) * dt + self.diffusion_state * config.diffusion_coeff + self.quantum_noise_cache * 0.01 + lorenz_mod
  let new_conductance := config.memristor_base_r / (config.memristor_base_r + Real.exp (-new_potential))
  let new_nested_levels := λ l => self.nested_levels l + input * Real.exp (-(l : ℝ) * 0.1)
  let spiked := new_potential > 1.0
  let final_potential := if spiked then 0.0 else new_potential
  let final_diffusion := if spiked then self.diffusion_state + 0.1 else self.diffusion_state
  { potential := final_potential, conductance := new_conductance, diffusion_state := final_diffusion, quantum_noise_cache := self.quantum_noise_cache, nested_levels := new_nested_levels }

lemma exp_mono : Monotone Real.exp := by
  intro a b h
  exact Real.exp_monotone h

noncomputable theorem potential_bounded : ∀ (self : DiffusiveNeuron) (input dt : ℝ) (config : JaideConfig),
  (∀ l, |self.nested_levels l| ≤ 1) →
  |input| ≤ 1 → 0 < dt ≤ 0.01 → config.diffusion_coeff ≤ 0.05 →
  let new_self := updateDiffusiveNeuron self input dt config
  |new_self.potential| ≤ 1 := by
  intros self input dt config h_nested h_input h_dt h_diff
  simp [updateDiffusiveNeuron]
  have h_abs_self : |self.potential| ≤ 1 := by linarith
  have h_abs_diff : |self.diffusion_state| ≤ 1 := by linarith
  have h_abs_quantum : |self.quantum_noise_cache| ≤ 1 := by linarith
  have h_lorenz_bound : |config.lorenz_sigma * (self.diffusion_state - self.potential) * dt| ≤ 10 * 2 * 0.01 := by
    calc |config.lorenz_sigma * (self.diffusion_state - self.potential) * dt| ≤ 10 * |self.diffusion_state - self.potential| * 0.01 := by
      linarith [h_dt]
    _ ≤ 10 * ( |self.diffusion_state| + |self.potential| ) * 0.01 := abs_sub_le _ _
    _ ≤ 10 * (1 + 1) * 0.01 := by linarith [h_abs_self, h_abs_diff]
  have h_base : |self.potential + (input - self.potential) * dt + self.diffusion_state * config.diffusion_coeff + self.quantum_noise_cache * 0.01 + lorenz_mod| ≤ 1 + 1 * 0.01 + 1 * 0.05 + 1 * 0.01 + 0.2 := by
    linarith [h_abs_self, h_input, h_abs_diff, h_diff, h_abs_quantum, h_lorenz_bound]
  have h_new_pot : |new_potential| ≤ 1.27 := by linarith [h_base]
  have h_final : |if new_potential > 1 then 0 else new_potential| ≤ 1 := by
    split_ifs
    · norm_num
    · exact le_trans (abs_le.2 ⟨h, le_of_lt h⟩) (by norm_num)
  exact h_final

noncomputable theorem diffusion_stable : ∀ (self : DiffusiveNeuron) (input dt : ℝ) (config : JaideConfig),
  |self.diffusion_state| ≤ 1 → |input| ≤ 1 → 0 < dt ≤ 0.01 →
  let new_self := updateDiffusiveNeuron self input dt config
  |new_self.diffusion_state| ≤ 1 + config.diffusion_coeff * dt := by
  intros self input dt config h_diff h_input h_dt
  simp [updateDiffusiveNeuron]
  split_ifs with h_spike
  · have : 0.1 ≤ config.diffusion_coeff * dt := by
      linarith [h_dt, le_trans (by norm_num) h_diff]
    calc |self.diffusion_state + 0.1| ≤ |self.diffusion_state| + 0.1 := abs_add _ _
    _ ≤ 1 + 0.1 := by linarith [h_diff]
    _ ≤ 1 + config.diffusion_coeff * dt := this
  · exact h_diff
