pub const ReversibleScaleFreeLayer = struct {
    weights_s: *Tensor,
    weights_t: *Tensor,
    bias_s: *Tensor,
    bias_t: *Tensor,
    allocator: Allocator,

    pub fn init(allocator: Allocator, size: usize) !*ReversibleScaleFreeLayer {
        var layer = try allocator.create(ReversibleScaleFreeLayer);
        const half = size / 2;
        layer.weights_s = try Tensor.randomNormal(allocator, &.{half, half}, .f64, 0.0, 0.02, 0);
        layer.weights_t = try Tensor.randomNormal(allocator, &.{half, half}, .f64, 0.0, 0.02, 1);
        layer.bias_s = try Tensor.zeros(allocator, &.{half}, .f64);
        layer.bias_t = try Tensor.zeros(allocator, &.{half}, .f64);
        layer.allocator = allocator;
        return layer;
    }

    pub fn deinit(self: *ReversibleScaleFreeLayer) void {
        self.weights_s.deinit();
        self.weights_t.deinit();
        self.bias_s.deinit();
        self.bias_t.deinit();
        self.allocator.destroy(self);
    }

    pub fn forward(self: *ReversibleScaleFreeLayer, input: *Tensor) !*Tensor {
        if (input.shape.dims.len != 1 or input.shape.dims[0] % 2 != 0) return error.InvalidInput;
        const half = input.shape.dims[0] / 2;
        var x1 = try input.slice(0, half);
        defer x1.deinit();
        var x2 = try input.slice(half, input.shape.dims[0]);
        defer x2.deinit();
        var s_x2 = try self.weights_s.matmul(x2);
        defer s_x2.deinit();
        s_x2 = try s_x2.add(self.bias_s);
        defer s_x2.deinit();
        var exp_s_x2 = try s_x2.exp();
        defer exp_s_x2.deinit();
        var y1 = try x1.mul(exp_s_x2);
        defer y1.deinit();
        var t_y1 = try self.weights_t.matmul(y1);
        defer t_y1.deinit();
        t_y1 = try t_y1.add(self.bias_t);
        defer t_y1.deinit();
        var y2 = try x2.add(t_y1);
        defer y2.deinit();
        return try y1.concat(y2, 0);
    }

    pub fn backward(self: *ReversibleScaleFreeLayer, grad_y: *Tensor, x: *const Tensor) !*Tensor {
        const half = grad_y.shape.dims[0] / 2;
        var gy1 = try grad_y.slice(0, half);
        defer gy1.deinit();
        var gy2 = try grad_y.slice(half, grad_y.shape.dims[0]);
        defer gy2.deinit();
        var x1 = try x.slice(0, half);
        defer x1.deinit();
        var x2 = try x.slice(half, x.shape.dims[0]);
        defer x2.deinit();
        var s_x2 = try self.weights_s.matmul(x2);
        defer s_x2.deinit();
        s_x2 = try s_x2.add(self.bias_s);
        defer s_x2.deinit();
        var exp_s_x2 = try s_x2.exp();
        defer exp_s_x2.deinit();
        var y1 = try x1.mul(exp_s_x2);
        defer y1.deinit();
        var gx2 = try gy2.copy();
        defer gx2.deinit();
        var gt_y1 = try gy2.copy();
        defer gt_y1.deinit();
        var gy1_wt = try self.weights_t.transpose().matmul(gt_y1);
        defer gy1_wt.deinit();
        var gexp_s_x2 = try gy1.mul(x1);
        defer gexp_s_x2.deinit();
        var gs_x2 = try gexp_s_x2.mul(exp_s_x2);
        defer gs_x2.deinit();
        var gx1 = try gy1.mul(exp_s_x2);
        defer gx1.deinit();
        var gx2_s = try self.weights_s.transpose().matmul(gs_x2);
        defer gx2_s.deinit();
        gx2 = try gx2.add(gx2_s);
        defer gx2.deinit();
        return try gx1.concat(gx2, 0);
    }
};

pub const RSFProcessor = struct {
    config: RSFConfig,
    allocator: Allocator,
    layers: [] *ReversibleScaleFreeLayer,

    pub fn init(allocator: Allocator, config: RSFConfig) !*RSFProcessor {
        var proc = try allocator.create(RSFProcessor);
        proc.config = config;
        proc.allocator = allocator;
        proc.layers = try allocator.alloc(*ReversibleScaleFreeLayer, config.num_layers);
        var i: usize = 0;
        while (i < config.num_layers) : (i += 1) {
            proc.layers[i] = try ReversibleScaleFreeLayer.init(allocator, config.hidden_size);
        }
        return proc;
    }

    pub fn deinit(self: *RSFProcessor) void {
        for (self.layers) |layer| {
            layer.deinit();
        }
        self.allocator.free(self.layers);
        self.allocator.destroy(self);
    }

    pub fn forward(self: *RSFProcessor, input: *Tensor) !*Tensor {
        var current = try input.copy();
        defer current.deinit();
        for (self.layers) |layer| {
            var next = try layer.forward(current);
            current.deinit();
            current = next;
        }
        return current;
    }

    pub fn backward(self: *RSFProcessor, grad_output: *Tensor, input: *const Tensor) !*Tensor {
        var current_grad = try grad_output.copy();
        defer current_grad.deinit();
        var current_input = input;
        var i: isize = @intCast(self.layers.len - 1);
        while (i >= 0) : (i -= 1) {
            var next_grad = try self.layers[@intCast(i)].backward(current_grad, current_input);
            current_grad.deinit();
            current_grad = next_grad;
            if (i > 0) {
                current_input = try current_input.slice(0, current_input.shape.dims[0]);
                defer current_input.deinit();
            }
        }
        return current_grad;
    }
};
entry forward [n] (inputs: [n]f32) (dt: f32) (noise: f32) (mod: f32) : [n]f32 =
  let potentials = map (\x -> x + dt * (noise - x) + mod) inputs
  let spiked = map (> 1.0f32) potentials
  let reset = map2 (\p s -> if s then 0.0f32 else p) potentials spiked
  in reset

entry backward [n] (grads: [n]f32) (params: [n]f32) (lr: f32) (fisher: [n]f32) : [n]f32 =
  let natural_grads = map2 (/) grads fisher
  in map2 (\p g -> p - lr * g) params natural_grads

entry diffusive_update [n] (states: [n]f32) (currents: [n]f32) (dt: f32) (diff_rate: f32) (seed: i32) : [n]f32 =
  let randoms = map (\i -> f32.i32 (i * 1103515245 + seed) / 2147483648.0f32 * 2.0f32 - 1.0f32) (iota n)
  in map3 (\s c r -> s + c * dt + diff_rate * r) states currents randoms

entry memristor_update [n] (resistances: [n]f32) (voltages: [n]f32) (dt: f32) : [n]f32 =
  map2 (\r v -> f32.max 100.0f32 (f32.min 10000.0f32 (r * f32.exp (-v * dt * 0.001f32)))) resistances voltages

entry hebbian_adjust [n] (conductances: [n]f32) (pre_spikes: [n]bool) (post_spikes: [n]bool) : [n]f32 =
  map3 (\c pre post ->
    let adj = if pre && post then 0.05f32 else if pre && !post then -0.03f32 else 0.0f32
    in f32.max 0.0001f32 (f32.min 0.01f32 (c * (1.0f32 + adj)))
  ) conductances pre_spikes post_spikes

entry astro_modulate [n] (times: [n]i32) (knots: [8]f32) : [n]f32 =
  map (\t ->
    let mods = map (\k -> f32.sin (f32.i32 t * 0.01f32 + k) * 0.1f32) knots
    in 1.0f32 + (reduce_comm (+, 0.0f32) mods)
  ) times

entry nested_update [n] (levels: [n][3]f32) (deltas: [n]f32) : [n][3]f32 =
  map2 (\lv dl ->
    map2 (\l idx -> l + dl * f32.exp (-f32.i32 idx * 0.1f32)) lv (iota 3)
  ) levels deltas

entry rsf_forward [n] (x: [n]f32) (ws: [m][n/2]f32) (wt: [m][n/2]f32) (bs: [m]f32) (bt: [m]f32) : [n]f32 =
  let m = length ws
  let half = n / 2
  let x1 = take half x
  let x2 = drop half x
  let sx2 = map (\i ->
    (reduce_comm (+, 0.0f32) (map (\j -> ws[i,j] * x2[j]) (iota half))) + bs[i]
  ) (iota m)
  let exp_sx2 = map f32.exp sx2
  let y1 = map2 (\i ex -> x1[i] * ex) (iota half) exp_sx2
  let ty1 = map (\i ->
    (reduce_comm (+, 0.0f32) (map (\j -> wt[i,j] * y1[j]) (iota half))) + bt[i]
  ) (iota m)
  let y2 = map2 (+) x2 ty1
  in y1 ++ y2

entry rsf_backward [n] (gy: [n]f32) (x: [n]f32) (ws: [m][n/2]f32) (wt: [m][n/2]f32) (bs: [m]f32) (bt: [m]f32) (lr: f32)
  : ([n]f32, [m][n/2]f32, [m][n/2]f32, [m]f32, [m]f32) =
  let m = length ws
  let half = n / 2
  let gy1 = take half gy
  let gy2 = drop half gy
  let x1 = take half x
  let x2 = drop half x
  let sx2 = map (\i ->
    (reduce_comm (+, 0.0f32) (map (\j -> ws[i,j] * x2[j]) (iota half))) + bs[i]
  ) (iota m)
  let exp_sx2 = map f32.exp sx2
  let y1 = map2 (\i ex -> x1[i] * ex) (iota half) exp_sx2
  let gx2 = replicate m gy2[0]
  let gt_y1 = replicate m gy2[0]
  let gwt = map (\i ->
    map (\j -> gt_y1[i] * y1[j]) (iota half)
  ) (iota m)
  let gbt = map (\i -> gt_y1[i]) (iota m)
  let gexp_s_x2 = map2 (\i g -> g * x1[i]) (iota half) gy1
  let gs_x2 = map2 (\i g -> g * exp_sx2[i]) (iota m) gexp_s_x2
  let gws = map (\i ->
    map (\j -> gs_x2[i] * x2[j]) (iota half)
  ) (iota m)
  let gbs = map (\i -> gs_x2[i]) (iota m)
  let gx1 = map2 (\i g -> g * exp_sx2[i]) (iota half) gy1
  let gx2_s = map (\i ->
    reduce_comm (+, 0.0f32) (map (\j -> ws[j,i] * gs_x2[j]) (iota m))
  ) (iota half)
  let gx2' = map2 (+) gx2 gx2_s
  let gx = gx1 ++ gx2'
  let ws_updated = map2 (\i row -> map2 (\j w -> w + lr * gws[i,j]) (iota half) row) (iota m) ws
  let wt_updated = map2 (\i row -> map2 (\j w -> w + lr * gwt[i,j]) (iota half) row) (iota m) wt
  let bs_updated = map2 (+) bs (map (*lr) gbs)
  let bt_updated = map2 (+) bt (map (*lr) gbt)
  in (gx, ws_updated, wt_updated, bs_updated, bt_updated)
