{-# LANGUAGE DataKinds, TypeOperators, DeriveGeneric, DeriveAnyClass, DeriveLift, FlexibleContexts, NoImplicitPrelude #-}
module Neuromorphic where

import Clash.Prelude
import GHC.Generics (Generic)
import Control.DeepSeq (NFData)

data MemristorState = MemristorState { resistance :: Signed 32, conductance :: Signed 32 }
  deriving (Show, Eq, Generic, NFData, BitPack)

data NeuronState = NeuronState { potential :: Signed 32, threshold :: Signed 32, refract :: Unsigned 8 }
  deriving (Show, Eq, Generic, NFData, BitPack)

{-# NOINLINE updateMemristor #-}
updateMemristor :: MemristorState -> Signed 32 -> MemristorState
updateMemristor (MemristorState r c) v = MemristorState r' c'
  where
    rCalc = r * (1024 + (v * (-1)) `shiftR` 10)
    r' = max 100 (min 10000 rCalc)
    c' = 1024 `div` r'

{-# NOINLINE hebbianAdjust #-}
hebbianAdjust :: MemristorState -> Bool -> Bool -> MemristorState
hebbianAdjust (MemristorState r c) pre post = MemristorState r' c'
  where
    adj = if pre && post then 51 else if pre && not post then -30 else 0
    cCalc = c * (1024 + adj) `shiftR` 10
    c' = max 1 (min 102 cCalc)
    r' = 1024 `div` c'

{-# NOINLINE updateNeuron #-}
updateNeuron :: NeuronState -> Signed 32 -> Signed 32 -> NeuronState
updateNeuron (NeuronState p t r) input dt = NeuronState p' t r'
  where
    decay = (p `shiftR` 7) * dt
    pNext = p + input - decay
    p' = if p >= t || r > 0 then 0 else pNext
    r' = if p >= t then 5 else if r > 0 then r - 1 else 0

spike :: NeuronState -> Bool
spike (NeuronState p t _) = p >= t

type LayerState = Vec 512 NeuronState

forwardLayer :: LayerState -> Vec 512 (Signed 32) -> Signed 32 -> LayerState
forwardLayer ns inputs dt = zipWith3 updateNeuron ns inputs (repeat dt)

topEntity :: Clock System -> Reset System -> Enable System
          -> Signal System (Vec 512 (Signed 32)) -> Signal System (Vec 512 Bool)
topEntity clk rst en inputs = output
  where
    initState = repeat (NeuronState 0 1024 0)
    ns = register initState (forwardLayer <$> ns <*> inputs <*> pure 1)
    output = map spike <$> ns
