def updateDiffusiveNeuron (self : DiffusiveNeuron) (input : ℝ) (dt : ℝ) (config : JaideConfig) : DiffusiveNeuron :=
  let lorenz_mod := config.lorenz_sigma * (self.diffusion_state - self.potential) * dt
  let new_potential := self.potential + (input - self.potential) * dt + self.diffusion_state * config.diffusion_coeff + self.quantum_noise_cache * 0.01 + lorenz_mod
  let new_conductance := config.memristor_base_r / (config.memristor_base_r + Real.exp (-new_potential))
  let new_nested_levels := λ (l : Fin 3) => self.nested_levels l + input * Real.exp (-(l : ℝ) * 0.1)
  let spiked := new_potential > 1.0
  let final_potential := if spiked then 0.0 else new_potential
  let final_diffusion := if spiked then self.diffusion_state + 0.1 else self.diffusion_state
  { potential := final_potential, conductance := new_conductance, diffusion_state := final_diffusion, quantum_noise_cache := self.quantum_noise_cache, nested_levels := new_nested_levels }

theorem potential_bounded (self : DiffusiveNeuron) (input dt : ℝ) (config : JaideConfig)
  (h_nested : ∀ l, |self.nested_levels l| ≤ 1)
  (h_input : |input| ≤ 1) (h_dt : 0 < dt ∧ dt ≤ 0.01) (h_diff : config.diffusion_coeff ≤ 0.05)
  (h_self_pot : |self.potential| ≤ 1) (h_self_diff : |self.diffusion_state| ≤ 1)
  (h_quantum : |self.quantum_noise_cache| ≤ 1) :
  let new_self := updateDiffusiveNeuron self input dt config
  |new_self.potential| ≤ 2.0 := by
  intro new_self
  simp [updateDiffusiveNeuron]
  split_ifs
  case pos =>
    norm_num
  case neg =>
    have h_term1 : |self.potential| ≤ 1 := h_self_pot
    have h_term2 : |(input - self.potential) * dt| ≤ 0.02 := by
      calc |(input - self.potential) * dt|
        _ = |input - self.potential| * |dt| := abs_mul _ _
        _ ≤ (|input| + |self.potential|) * 0.01 := mul_le_mul (abs_sub _ _) (le_of_lt h_dt.2) (abs_nonneg _) (add_nonneg (abs_nonneg _) (abs_nonneg _))
        _ ≤ (1 + 1) * 0.01 := mul_le_mul (add_le_add h_input h_self_pot) (le_refl _) (by norm_num) (by norm_num)
        _ = 0.02 := by norm_num
    have h_term3 : |self.diffusion_state * config.diffusion_coeff| ≤ 0.05 := by
      calc |self.diffusion_state * config.diffusion_coeff|
        _ = |self.diffusion_state| * |config.diffusion_coeff| := abs_mul _ _
        _ ≤ 1 * 0.05 := mul_le_mul h_self_diff (le_trans (le_abs_self _) h_diff) (abs_nonneg _) (by norm_num)
        _ = 0.05 := by norm_num
    have h_total : |self.potential + (input - self.potential) * dt + self.diffusion_state * config.diffusion_coeff + self.quantum_noise_cache * 0.01| ≤ 1.08 := by
      calc |self.potential + (input - self.potential) * dt + self.diffusion_state * config.diffusion_coeff + self.quantum_noise_cache * 0.01|
        _ ≤ |self.potential| + |(input - self.potential) * dt| + |self.diffusion_state * config.diffusion_coeff| + |self.quantum_noise_cache * 0.01| := by repeat apply abs_add
        _ ≤ 1 + 0.02 + 0.05 + 0.01 := add_le_add (add_le_add (add_le_add h_self_pot h_term2) h_term3) (mul_le_mul h_quantum (le_refl _) (by norm_num) (by norm_num))
        _ = 1.08 := by norm_num
    apply le_trans h_total
    norm_num

theorem diffusion_stable (self : DiffusiveNeuron) (input dt : ℝ) (config : JaideConfig)
  (h_diff_state : |self.diffusion_state| ≤ 1) (h_input : |input| ≤ 1) (h_dt : 0 < dt ∧ dt ≤ 0.01) :
  let new_self := updateDiffusiveNeuron self input dt config
  |new_self.diffusion_state| ≤ |self.diffusion_state| + 0.1 := by
  intro new_self
  simp [updateDiffusiveNeuron]
  split_ifs
  case pos =>
    calc |self.diffusion_state + 0.1|
      _ ≤ |self.diffusion_state| + |0.1| := abs_add _ _
      _ = |self.diffusion_state| + 0.1 := by norm_num
  case neg =>
    linarith
