const std = @import("std");
const Allocator = std.mem.Allocator;
const math = std.math;

pub const Tensor = struct {
    data: []f64,
    shape: struct { dims: []const usize },
    allocator: Allocator,

    pub fn zeros(allocator: Allocator, dims: []const usize) !*Tensor {
        var t = try allocator.create(Tensor);
        var size: usize = 1;
        for (dims) |d| size *= d;
        t.data = try allocator.alloc(f64, size);
        @memset(t.data, 0);
        t.shape.dims = try allocator.dupe(usize, dims);
        t.allocator = allocator;
        return t;
    }

    pub fn randomNormal(allocator: Allocator, dims: []const usize, _: type, mean: f64, stddev: f64, seed: u64) !*Tensor {
        var t = try zeros(allocator, dims);
        var prng = std.rand.DefaultPrng.init(seed);
        const random = prng.random();
        for (t.data) |*v| {
            v.* = random.floatNorm(f64) * stddev + mean;
        }
        return t;
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape.dims);
        self.allocator.destroy(self);
    }

    pub fn slice(self: *const Tensor, start: usize, end: usize) !*Tensor {
        const total_dim = self.shape.dims[0];
        const width = self.data.len / total_dim;
        const new_rows = end - start;
        const new_size = new_rows * width;
        var t = try self.allocator.create(Tensor);
        t.data = try self.allocator.alloc(f64, new_size);
        const src_start = start * width;
        @memcpy(t.data, self.data[src_start .. src_start + new_size]);
        var new_dims = try self.allocator.dupe(usize, self.shape.dims);
        new_dims[0] = new_rows;
        t.shape.dims = new_dims;
        t.allocator = self.allocator;
        return t;
    }

    pub fn copy(self: *const Tensor) !*Tensor {
        var t = try self.allocator.create(Tensor);
        t.data = try self.allocator.dupe(f64, self.data);
        t.shape.dims = try self.allocator.dupe(usize, self.shape.dims);
        t.allocator = self.allocator;
        return t;
    }

    pub fn matmul(self: *const Tensor, other: *const Tensor) !*Tensor {
        const m = self.shape.dims[0];
        const k = self.shape.dims[1];
        const n = other.shape.dims[1];
        if (self.shape.dims[1] != other.shape.dims[0]) return error.DimensionMismatch;
        var t = try zeros(self.allocator, &.{m, n});
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                var sum: f64 = 0;
                var l: usize = 0;
                while (l < k) : (l += 1) {
                    sum += self.data[i * k + l] * other.data[l * n + j];
                }
                t.data[i * n + j] = sum;
            }
        }
        return t;
    }

    pub fn add(self: *const Tensor, other: *const Tensor) !*Tensor {
        if (self.data.len != other.data.len) return error.DimensionMismatch;
        var t = try self.copy();
        for (t.data, 0..) |*v, i| {
            v.* += other.data[i];
        }
        return t;
    }

    pub fn mul(self: *const Tensor, other: *const Tensor) !*Tensor {
        if (self.data.len != other.data.len) return error.DimensionMismatch;
        var t = try self.copy();
        for (t.data, 0..) |*v, i| {
            v.* *= other.data[i];
        }
        return t;
    }

    pub fn exp(self: *const Tensor) !*Tensor {
        var t = try self.copy();
        for (t.data) |*v| {
            v.* = math.exp(v.*);
        }
        return t;
    }

    pub fn concat(self: *const Tensor, other: *const Tensor, dim: usize) !*Tensor {
        if (dim != 0) return error.UnsupportedDim;
        var t = try self.allocator.create(Tensor);
        t.data = try self.allocator.alloc(f64, self.data.len + other.data.len);
        @memcpy(t.data[0..self.data.len], self.data);
        @memcpy(t.data[self.data.len..], other.data);
        var new_dims = try self.allocator.dupe(usize, self.shape.dims);
        new_dims[0] += other.shape.dims[0];
        t.shape.dims = new_dims;
        t.allocator = self.allocator;
        return t;
    }

    pub fn transpose(self: *const Tensor) !*Tensor {
        if (self.shape.dims.len != 2) return error.InvalidShape;
        const rows = self.shape.dims[0];
        const cols = self.shape.dims[1];
        var t = try zeros(self.allocator, &.{cols, rows});
        var i: usize = 0;
        while (i < rows) : (i += 1) {
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                t.data[j * rows + i] = self.data[i * cols + j];
            }
        }
        return t;
    }
};
