const std = @import("std");
const Allocator = std.mem.Allocator;
const Tensor = @import("types.zig").Tensor;

pub const RSFConfig = struct {
    num_layers: usize = 12,
    hidden_size: usize = 2048,
    activation: enum { relu, gelu, silu } = .gelu,
};

pub const ReversibleScaleFreeLayer = struct {
    weights_s: *Tensor,
    weights_t: *Tensor,
    bias_s: *Tensor,
    bias_t: *Tensor,
    allocator: Allocator,

    pub fn init(allocator: Allocator, size: usize) !*ReversibleScaleFreeLayer {
        var layer = try allocator.create(ReversibleScaleFreeLayer);
        const half = size / 2;
        layer.weights_s = try Tensor.randomNormal(allocator, &.{half, half}, f64, 0.0, 0.02, 0);
        layer.weights_t = try Tensor.randomNormal(allocator, &.{half, half}, f64, 0.0, 0.02, 1);
        layer.bias_s = try Tensor.zeros(allocator, &.{half});
        layer.bias_t = try Tensor.zeros(allocator, &.{half});
        layer.allocator = allocator;
        return layer;
    }

    pub fn deinit(self: *ReversibleScaleFreeLayer) void {
        self.weights_s.deinit();
        self.weights_t.deinit();
        self.bias_s.deinit();
        self.bias_t.deinit();
        self.allocator.destroy(self);
    }

    pub fn forward(self: *ReversibleScaleFreeLayer, input: *Tensor) !*Tensor {
        if (input.shape.dims.len != 1 or input.shape.dims[0] % 2 != 0) return error.InvalidInput;
        const half = input.shape.dims[0] / 2;
        var x1 = try input.slice(0, half);
        defer x1.deinit();
        var x2 = try input.slice(half, input.shape.dims[0]);
        defer x2.deinit();
        var s_x2 = try self.weights_s.matmul(x2);
        defer s_x2.deinit();
        var s_x2_b = try s_x2.add(self.bias_s);
        defer s_x2_b.deinit();
        var exp_s_x2 = try s_x2_b.exp();
        defer exp_s_x2.deinit();
        var y1 = try x1.mul(exp_s_x2);
        defer y1.deinit();
        var t_y1 = try self.weights_t.matmul(y1);
        defer t_y1.deinit();
        var t_y1_b = try t_y1.add(self.bias_t);
        defer t_y1_b.deinit();
        var y2 = try x2.add(t_y1_b);
        defer y2.deinit();
        return try y1.concat(y2, 0);
    }

    pub fn backward(self: *ReversibleScaleFreeLayer, grad_y: *Tensor, x: *const Tensor) !*Tensor {
        const half = grad_y.shape.dims[0] / 2;
        var gy1 = try grad_y.slice(0, half);
        defer gy1.deinit();
        var gy2 = try grad_y.slice(half, grad_y.shape.dims[0]);
        defer gy2.deinit();
        var x1 = try x.slice(0, half);
        defer x1.deinit();
        var x2 = try x.slice(half, x.shape.dims[0]);
        defer x2.deinit();
        var s_x2 = try self.weights_s.matmul(x2);
        defer s_x2.deinit();
        var s_x2_b = try s_x2.add(self.bias_s);
        defer s_x2_b.deinit();
        var exp_s_x2 = try s_x2_b.exp();
        defer exp_s_x2.deinit();
        var t_wt = try self.weights_t.transpose();
        defer t_wt.deinit();
        var gy1_wt = try t_wt.matmul(gy2);
        defer gy1_wt.deinit();
        var gexp_s_x2 = try gy1.mul(x1);
        defer gexp_s_x2.deinit();
        var gs_x2 = try gexp_s_x2.mul(exp_s_x2);
        defer gs_x2.deinit();
        var gx1 = try gy1.mul(exp_s_x2);
        defer gx1.deinit();
        var t_ws = try self.weights_s.transpose();
        defer t_ws.deinit();
        var gx2_s = try t_ws.matmul(gs_x2);
        defer gx2_s.deinit();
        var gx2 = try gy2.add(gx2_s);
        defer gx2.deinit();
        return try gx1.concat(gx2, 0);
    }
};

pub const RSFProcessor = struct {
    config: RSFConfig,
    allocator: Allocator,
    layers: []*ReversibleScaleFreeLayer,

    pub fn init(allocator: Allocator, config: RSFConfig) !*RSFProcessor {
        var proc = try allocator.create(RSFProcessor);
        proc.config = config;
        proc.allocator = allocator;
        proc.layers = try allocator.alloc(*ReversibleScaleFreeLayer, config.num_layers);
        var i: usize = 0;
        while (i < config.num_layers) : (i += 1) {
            proc.layers[i] = try ReversibleScaleFreeLayer.init(allocator, config.hidden_size);
        }
        return proc;
    }

    pub fn deinit(self: *RSFProcessor) void {
        for (self.layers) |layer| {
            layer.deinit();
        }
        self.allocator.free(self.layers);
        self.allocator.destroy(self);
    }

    pub fn forward(self: *RSFProcessor, input: *Tensor) !*Tensor {
        var current = try input.copy();
        for (self.layers) |layer| {
            var next = try layer.forward(current);
            current.deinit();
            current = next;
        }
        return current;
    }

    pub fn backward(self: *RSFProcessor, grad_output: *Tensor, input: *const Tensor) !*Tensor {
        var current_grad = try grad_output.copy();
        var current_input = try input.copy();
        defer current_input.deinit(); 
        var i: isize = @intCast(self.layers.len);
        i -= 1;
        while (i >= 0) : (i -= 1) {
            const idx: usize = @intCast(i);
            var next_grad = try self.layers[idx].backward(current_grad, current_input);
            current_grad.deinit();
            current_grad = next_grad;
        }
        return current_grad;
    }
};
