const std = @import("std");
const mem = std.mem;
const math = std.math;
const rand = std.rand;
const atomic = std.atomic;
const time = std.time;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.AutoHashMap;
const DefaultPrng = rand.DefaultPrng;
const c = @cImport({
    @cInclude("sys/mman.h");
    @cInclude("sys/stat.h");
    @cInclude("fcntl.h");
    @cInclude("unistd.h");
    @cInclude("zlib.h");
});

pub const MemoryConfig = struct {
    max_blocks: usize = 1_000_000,
    block_size: usize = 4096,
    alignment: u29 = 64,
    enable_prefetch: bool = true,
    use_huge_pages: bool = false,
    track_allocations: bool = true,
    max_alloc_size: usize = 1 << 30,
    min_alloc_size: usize = 64,
    enable_compression: bool = false,
    compression_level: i32 = 6,
    enable_logging: bool = false,
    enable_validation: bool = true,
    validation_rate: f32 = 0.01,
    enable_mlock: bool = false,
    enable_mmap: bool = true,
    enable_posix_fallocate: bool = true,
    enable_fsync: bool = false,
    enable_monitor: bool = false,
    monitor_interval: u64 = 1_000_000_000,
    enable_purger: bool = true,
    purger_interval: u64 = 5_000_000_000,
};

pub const MemoryBlock = struct {
    data: []u8,
    orig_data: ?[]u8 = null,
    size: usize,
    capacity: usize,
    offset: usize,
    next: ?*MemoryBlock = null,
    prev: ?*MemoryBlock = null,
    id: u64,
    flags: u32,
    timestamp: atomic.Value(u64),
    checksum: atomic.Value(u32),
    ref_count: atomic.Value(usize),
    allocator: Allocator,
    lock: std.Thread.Mutex,
    fd: i32 = -1,
    compressed: bool = false,
    dedup_hash: u64 = 0,
    is_mmap: bool = false,
    compression_level: i32 = 6,

    pub fn init(allocator: Allocator, config: MemoryConfig) !*MemoryBlock {
        var block = try allocator.create(MemoryBlock);
        const alloc_data = try allocator.alignedAlloc(u8, config.alignment, config.block_size);
        block.* = .{
            .data = alloc_data,
            .size = 0,
            .capacity = config.block_size,
            .offset = 0,
            .id = @intCast(time.milliTimestamp()),
            .flags = 0,
            .timestamp = atomic.Value(u64).init(@intCast(time.milliTimestamp())),
            .checksum = atomic.Value(u32).init(0),
            .ref_count = atomic.Value(usize).init(1),
            .allocator = allocator,
            .lock = std.Thread.Mutex{},
            .is_mmap = false,
            .compression_level = config.compression_level,
        };
        if (config.use_huge_pages) {
            _ = c.madvise(block.data.ptr, block.capacity, c.MADV_HUGEPAGE);
        }
        if (config.enable_mlock) {
            _ = c.mlock(block.data.ptr, block.capacity);
        }
        if (config.enable_mmap) {
            var path_buf: [64]u8 = undefined;
            const path = try std.fmt.bufPrintZ(&path_buf, "/tmp/mem_block_{d}", .{block.id});
            block.fd = c.open(path.ptr, c.O_RDWR | c.O_CREAT | c.O_EXCL, 0o600);
            if (block.fd != -1) {
                _ = c.ftruncate(block.fd, @intCast(block.capacity));
                const mmap_ptr = c.mmap(null, block.capacity, c.PROT_READ | c.PROT_WRITE, c.MAP_SHARED, block.fd, 0);
                if (mmap_ptr != c.MAP_FAILED) {
                    block.data = @as([*]u8, @ptrCast(mmap_ptr))[0..block.capacity];
                    block.is_mmap = true;
                    block.orig_data = alloc_data;
                } else {
                     _ = c.close(block.fd);
                     block.fd = -1;
                }
            }
        }
        if (config.enable_posix_fallocate and block.fd != -1) {
            _ = c.posix_fallocate(block.fd, 0, @intCast(block.capacity));
        }
        return block;
    }

    pub fn deinit(self: *MemoryBlock) void {
        self.lock.lock();
        if (self.fd != -1) {
            if (self.is_mmap) {
                _ = c.munmap(self.data.ptr, self.capacity);
            }
            _ = c.close(self.fd);
        }
        if (self.is_mmap) {
            if (self.orig_data) |orig| {
                self.allocator.free(orig);
            }
        } else {
            self.allocator.free(self.data);
        }
        self.lock.unlock();
        self.allocator.destroy(self);
    }

    pub fn write(self: *MemoryBlock, data: []const u8) !void {
        self.lock.lock();
        defer self.lock.unlock();
        if (self.size + data.len > self.capacity) return error.OutOfMemory;
        @memcpy(self.data[self.offset + self.size .. self.offset + self.size + data.len], data);
        self.size += data.len;
        const new_ts = @intCast(time.milliTimestamp());
        self.timestamp.store(new_ts, .SeqCst);
        const crc = c.crc32(0, self.data[self.offset..].ptr, @intCast(self.size));
        self.checksum.store(@intCast(crc), .SeqCst);
    }

    pub fn compress(self: *MemoryBlock) !void {
        const bound = c.compressBound(@intCast(self.size));
        var comp_buffer = try self.allocator.alloc(u8, bound);
        defer self.allocator.free(comp_buffer);
        var comp_len: c.uLongf = @intCast(comp_buffer.len);
        const ret = c.compress(comp_buffer.ptr, &comp_len, self.data[self.offset..].ptr, @intCast(self.size));
        if (ret == c.Z_OK) {
            @memcpy(self.data[self.offset..self.offset + comp_len], comp_buffer[0..comp_len]);
            self.size = comp_len;
            self.compressed = true;
        }
    }

    pub fn decompress(self: *MemoryBlock) !void {
        if (!self.compressed) return;
        var decomp_buffer = try self.allocator.alloc(u8, self.capacity);
        defer self.allocator.free(decomp_buffer);
        var decomp_len: c.uLongf = @intCast(decomp_buffer.len);
        const ret = c.uncompress(decomp_buffer.ptr, &decomp_len, self.data[self.offset..].ptr, @intCast(self.size));
        if (ret == c.Z_OK) {
            @memcpy(self.data[self.offset..self.offset + decomp_len], decomp_buffer[0..decomp_len]);
            self.size = decomp_len;
            self.compressed = false;
        }
    }
};

pub const MemoryPool = struct {
    config: MemoryConfig,
    allocator: Allocator,
    free_blocks: ArrayList(*MemoryBlock),
    used_blocks: HashMap(u64, *MemoryBlock),
    lock: std.Thread.Mutex,
    stats: struct {
        total_allocs: atomic.Value(u64),
        total_frees: atomic.Value(u64),
        peak_usage: atomic.Value(usize),
    },

    pub fn init(allocator: Allocator, config: MemoryConfig) !*MemoryPool {
        var pool = try allocator.create(MemoryPool);
        pool.* = .{
            .config = config,
            .allocator = allocator,
            .free_blocks = ArrayList(*MemoryBlock).init(allocator),
            .used_blocks = HashMap(u64, *MemoryBlock).init(allocator),
            .lock = std.Thread.Mutex{},
            .stats = .{
                .total_allocs = atomic.Value(u64).init(0),
                .total_frees = atomic.Value(u64).init(0),
                .peak_usage = atomic.Value(usize).init(0),
            },
        };
        var i: usize = 0;
        while (i < config.max_blocks) : (i += 1) {
            const block = try MemoryBlock.init(pool.allocator, config);
            try pool.free_blocks.append(block);
        }
        if (config.enable_monitor) {
            const thread = try std.Thread.spawn(.{}, monitorThread, .{pool});
            thread.detach();
        }
        if (config.enable_purger) {
            const purger_thread = try std.Thread.spawn(.{}, purgerThread, .{pool});
            purger_thread.detach();
        }
        return pool;
    }

    pub fn deinit(self: *MemoryPool) void {
        for (self.free_blocks.items) |block| {
            block.deinit();
        }
        self.free_blocks.deinit();
        var it = self.used_blocks.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.*.deinit();
        }
        self.used_blocks.deinit();
        self.allocator.destroy(self);
    }

    pub fn alloc(self: *MemoryPool, size: usize) !*MemoryBlock {
        self.lock.lock();
        defer self.lock.unlock();
        if (size > self.config.max_alloc_size or size < self.config.min_alloc_size) return error.InvalidSize;
        if (self.free_blocks.popOrNull()) |block| {
            try self.used_blocks.put(block.id, block);
            _ = self.stats.total_allocs.fetchAdd(1, .SeqCst);
            const current_usage = self.used_blocks.count() * self.config.block_size;
            _ = self.stats.peak_usage.fetchMax(current_usage, .SeqCst);
            if (self.config.enable_validation) {
                try self.validateBlock(block);
            }
            return block;
        } else {
            return error.OutOfMemory;
        }
    }

    pub fn free(self: *MemoryPool, block: *MemoryBlock) !void {
        self.lock.lock();
        defer self.lock.unlock();
        _ = self.used_blocks.remove(block.id);
        try self.free_blocks.append(block);
        _ = self.stats.total_frees.fetchAdd(1, .SeqCst);
    }

    fn monitorThread(pool: *MemoryPool) void {
        while (true) {
            std.time.sleep(pool.config.monitor_interval);
            const allocs = pool.stats.total_allocs.load(.SeqCst);
            const frees = pool.stats.total_frees.load(.SeqCst);
            _ = allocs; _ = frees;
        }
    }

    fn purgerThread(pool: *MemoryPool) void {
        while (true) {
            std.time.sleep(pool.config.purger_interval);
            pool.lock.lock();
            var to_purge = ArrayList(u64).init(pool.allocator);
            defer to_purge.deinit();
            var it = pool.used_blocks.iterator();
            const now = @intCast(std.time.milliTimestamp());
            while (it.next()) |entry| {
                const ts = entry.value_ptr.*.timestamp.load(.Acquire);
                if (now - @intCast(ts) > 3600000) {
                    to_purge.append(entry.key_ptr.*) catch {};
                }
            }
            for (to_purge.items) |id| {
                if (pool.used_blocks.get(id)) |block| {
                    pool.used_blocks.remove(id);
                    pool.free_blocks.append(block) catch {};
                }
            }
            pool.lock.unlock();
        }
    }

    fn validateBlock(_: *MemoryPool, block: *MemoryBlock) !void {
        block.lock.lock();
        defer block.lock.unlock();
        const crc = c.crc32(0, block.data[block.offset..].ptr, @intCast(block.size));
        const stored = block.checksum.load(.Acquire);
        if (@as(u32, @intCast(crc)) != stored) return error.ChecksumMismatch;
    }
};
