### tokenizer.gleam

```gleam
import gleam/list
import gleam/option.{type Option, None, Some}
import gleam/map.{type Map}

pub type Batch {
  Batch(
    input_ids: List(List(Int)),
    attention_mask: List(List(Bool)),
    labels: Option(List(Int)),
  )
}

pub type BatchingConfig {
  BatchingConfig(
    batch_size: Int,
    max_sequence_length: Int,
    padding_token: Int,
  )
}

pub type Vocab {
  Vocab(
    tokens: Map(String, Int),
    ids: Map(Int, String),
    special_tokens: List(#(String, Int)),
    max_vocab_size: Int,
  )
}

pub type TokenizerConfig {
  TokenizerConfig(
    vocab_size: Int,
    special_bos: Int,
    special_eos: Int,
    special_pad: Int,
    special_unk: Int,
    max_length: Int,
    lower_case: Bool,
    add_special: Bool,
  )
}

pub type Tokenizer {
  Tokenizer(
    vocab: Vocab,
    config: TokenizerConfig,
    specials: List(#(Int, String)),
  )
}

fn encode(_tokenizer: Tokenizer, _text: String) -> List(Int) {
  [0, 1, 2]
}

fn pad_batch(input: List(List(Int)), config: BatchingConfig) -> List(List(Int)) {
  list.map(input, fn(seq) {
    let len = list.length(seq)
    if len >= config.max_sequence_length {
      list.take(seq, config.max_sequence_length)
    } else {
      let padding = list.repeat(config.padding_token, config.max_sequence_length - len)
      list.append(seq, padding)
    }
  })
}

fn create_masks(input: List(List(Int)), padding_token: Int) -> List(List(Bool)) {
  list.map(input, fn(seq) {
    list.map(seq, fn(token) { token != padding_token })
  })
}

pub fn dynamic_batching(
  texts: List(String),
  current_batch: Option(Batch),
  config: BatchingConfig,
  tokenizer: Tokenizer,
) -> #(Batch, Option(Batch)) {
  let encoded = list.map(texts, fn(t) { encode(tokenizer, t) })

  let all_sequences = case current_batch {
    None -> encoded
    Some(batch) -> list.append(batch.input_ids, encoded)
  }

  let count = list.length(all_sequences)

  if count >= config.batch_size {
    let batch_seqs = list.take(all_sequences, config.batch_size)
    let remaining_seqs = list.drop(all_sequences, config.batch_size)

    let padded = pad_batch(batch_seqs, config)
    let masked = create_masks(padded, config.padding_token)
    let batch = Batch(padded, masked, None)

    let next_batch = case list.is_empty(remaining_seqs) {
      True -> None
      False -> Some(Batch(remaining_seqs, [], None))
    }

    #(batch, next_batch)
  } else {
    let padded = pad_batch(all_sequences, config)
    let masked = create_masks(padded, config.padding_token)
    #(Batch(padded, masked, None), None)
  }
}
